import{_ as e,c as r,o as t,af as o}from"./chunks/framework.r60quYNK.js";const p=JSON.parse('{"title":"南京旅行杂谈 - 2023","description":"","frontmatter":{},"headers":[],"relativePath":"2_articles/travel_record/NanJing.md","filePath":"2_articles/travel_record/NanJing.md"}'),n={name:"2_articles/travel_record/NanJing.md"};function i(l,a,c,d,_,s){return t(),r("div",null,a[0]||(a[0]=[o('<h1 id="南京旅行杂谈-2023" tabindex="-1">南京旅行杂谈 - 2023 <a class="header-anchor" href="#南京旅行杂谈-2023" aria-label="Permalink to &quot;南京旅行杂谈 - 2023&quot;">​</a></h1><h2 id="_4月29日-5月1日-☀️" tabindex="-1">4月29日 - 5月1日 ☀️ <a class="header-anchor" href="#_4月29日-5月1日-☀️" aria-label="Permalink to &quot;4月29日 - 5月1日 ☀️&quot;">​</a></h2><blockquote><p>因为记录博客时南京之旅已经过了整整两年，很多细节都忘记了，所以这次旅行记录就大概谈谈我当时的感受吧，不知道未来的我们看到这篇博客会不会掉眼泪呢🥰</p></blockquote><h3 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h3><p>南京是我和女朋友第一次一起旅行的地方，从21年9月上大学开始，我们就保持了一年多一千多公里的异地，大一因为没钱加上疫情，每次都只有放寒暑假才能回家见面，大二疫情放开，我们一起商量在两个城市中间找一座城市去见面，这样两个人花钱都少而且快，在盯着那份中国地图看了好久后，两个没钱的小孩决定五一去南京见面。</p><h3 id="买票" tabindex="-1">买票 <a class="header-anchor" href="#买票" aria-label="Permalink to &quot;买票&quot;">​</a></h3><p>这两个没钱没时间但思念心切的小孩，只能顶着五一假期的巨大人流量去南京，提前14天放票开始抢，抢到最后一天也只抢到两张无座票，两个小孩都在火车上站了一晚上十个小时，刚到南京的时候一个比一个累，直接在酒店睡了一上午才出去逛。</p><h3 id="_4月29日" tabindex="-1">4月29日 <a class="header-anchor" href="#_4月29日" aria-label="Permalink to &quot;4月29日&quot;">​</a></h3><p>第一天下午我们一起逛了明孝陵，我因为太累困的直接在明孝陵的板凳上睡着了，晚上去了哪里有点忘记了，需要等待女盆友补充🥰</p><p><code>最后更新时间：2025-06-30 20:27:40</code></p>',10)]))}const u=e(n,[["render",i]]);export{p as __pageData,u as default};
